// Galactic Racer reference data, generated by tools/import_swgr.py. Don't edit the JSON by hand —
// re-run the importer so it stays in step with the datamine.
const planets = require('../data/swgr/planets.json')
const tracks = require('../data/swgr/tracks.json')
const { categories, vehicleClasses, events } = require('../data/swgr/arcade.json')
const scenarios = require('../data/swgr/scenarios.json')
const { families: abilityFamilies, abilities } = require('../data/swgr/abilities.json')
const { classes, vehicles } = require('../data/swgr/vehicles.json')
const favors = require('../data/swgr/favors.json')
const rivals = require('../data/swgr/rivals.json')
const mysteries = require('../data/swgr/mysteries.json')
const statuses = require('../data/swgr/statuses.json')
const sponsors = require('../data/swgr/sponsors.json')
const tales = require('../data/swgr/tales.json')
// Achievements (the game's list, with Steam's icons, hidden flags and progress targets) and our groups of them
const { groups: achievementGroups, achievements } = require('../data/swgr/achievements.json')
const { palettes, patterns, patinas } = require('../data/swgr/liveries.json')
const characters = require('../data/swgr/characters.json')
// A character's emoji: their headshot (the racers) or hologram portrait (everyone else)
const characterEmojiByName = Object.fromEntries(characters.map(c => [c.name, c.emoji]))
// The racers you can pick in multiplayer (character cards): bio, multiplayer styles and builds, speeders, campaign links
const racers = require('../data/swgr/racers.json')
const styles = require('../data/swgr/styles.json')
const { keywords: partKeywords, parts } = require('../data/swgr/parts.json')

const byId = list => Object.fromEntries(list.map(item => [item.id, item]))
const planetById = byId(planets)
const trackById = byId(tracks)
const eventById = byId(events)
const categoryById = byId(categories)
const scenarioById = byId(scenarios)
const abilityById = byId(abilities)
const vehicleById = byId(vehicles)
const favorById = byId(favors)
const rivalById = byId(rivals)
const racerById = byId(racers)
const mysteryById = byId(mysteries)
const statusById = byId(statuses)
const sponsorById = byId(sponsors)
const taleById = byId(tales)
const achievementById = byId(achievements)
const achievementGroupById = byId(achievementGroups)
const paletteById = byId(palettes)
const patinaById = byId(patinas)
const patternById = byId(patterns)
const classById = byId(classes)
const abilityByName = Object.fromEntries(abilities.map(a => [a.name, a]))
const styleById = byId(styles)
const partById = byId(parts)
const partByName = Object.fromEntries(parts.map(p => [p.name, p]))

// A part's family as a list of parts (a part without tiers is a family of one); its key is the first tier's id
const familyOf = p => p.family.length > 1 ? p.family.map(id => partById[id]) : [p]

// Autocomplete: names that start with the query rank above names that merely contain it.
function search(list, query, label = item => item.name) {
    const q = query.trim().toLowerCase()
    const scored = list
        .map(item => {
            const name = item.name.toLowerCase()
            const score = !q ? 1 : name.startsWith(q) ? 3 : name.includes(q) ? 2 : label(item).toLowerCase().includes(q) ? 1 : 0
            return { item, score }
        })
        .filter(x => x.score > 0)
        .sort((a, b) => b.score - a.score)
    return scored.slice(0, 25).map(({ item }) => ({ name: label(item).slice(0, 100), value: item.id }))
}

module.exports = {
    planets,
    tracks,
    events,
    categories,
    scenarios,
    styles,
    abilities,
    abilityFamilies,
    classes,
    vehicles,
    favors,
    rivals,
    mysteries,
    statuses,
    sponsors,
    tales,
    achievements,
    achievementGroups,
    characters,
    racers,
    palettes,
    patterns,
    patinas,
    parts,
    vehicleClass: name => vehicleClasses[name],
    planet: id => planetById[id],
    track: id => trackById[id],
    event: id => eventById[id],
    category: id => categoryById[id],
    scenario: id => scenarioById[id],
    ability: id => abilityById[id],
    vehicle: id => vehicleById[id],
    favor: id => favorById[id],
    rival: id => rivalById[id],
    racer: id => racerById[id],
    mystery: id => mysteryById[id],
    status: id => statusById[id],
    sponsor: id => sponsorById[id],
    tale: id => taleById[id],
    achievement: id => achievementById[id],
    achievementGroup: id => achievementGroupById[id],
    achievementsInGroup: id => achievements.filter(a => a.group == id),
    // "Soren Zaks & Ary Quill" -> Soren's; "Q-33N (Broker backer)" -> Q-33N's
    characterEmoji: name => { const n = (name ?? '').split(/ & | \(/)[0].trim(); return characterEmojiByName[name] ?? characterEmojiByName[n] ?? null },
    palette: id => paletteById[id],
    pattern: id => patternById[id],
    patina: id => patinaById[id],
    palettesIn: group => palettes.filter(p => p.group == group),
    patternsFor: className => patterns.filter(p => p.class == className),
    vehicleByName: name => vehicles.find(v => v.name == name),
    vehicleClassById: id => classById[id],
    vehiclesInClass: name => vehicles.filter(v => v.class == name),
    abilityByName: name => abilityByName[name],
    // A family's abilities, by tier
    abilitiesInFamily: id => abilities.filter(a => a.family == id).sort((a, b) => a.tier - b.tier),
    style: id => styleById[id],
    part: id => partById[id],
    partByName: name => partByName[name],
    familyOf,
    partKeywords,
    // Parts that mention every given keyword (by keyword id); all parts for none
    partsWithKeywords: ids => {
        const names = ids.map(id => partKeywords[id]?.name).filter(Boolean)
        return parts.filter(p => names.every(n => p.keywords.includes(n)))
    },
    tracksOnPlanet: id => tracks.filter(t => t.planet == id),
    eventsOnTrack: id => events.filter(e => e.track == id),
    eventsInCategory: id => events.filter(e => e.category == id),
    // Scenarios whose schedule can draw this track
    scenariosOnTrack: id => scenarios.filter(sc => sc.schedule.some(d => d.tracks.some(t => t.track == id))),
    search,
}
